using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTests;

public sealed class CalculatePayableTotalTests
{
    // Feature: Loyalty discount (see .copilot-tracking/skraft-plans/pricing/features/discount.feature)
    // Payable total = subtotal - discount, where discount follows tier rate + order-size bonus,
    // capped at a 10-point ceiling, applied to the original subtotal and rounded down to the cent.

    [Theory]
    // Each band threshold belongs to the band above it, so a larger order can pay less.
    [InlineData(LoyaltyTier.Bronze, 4999, 4750)]
    [InlineData(LoyaltyTier.Bronze, 5000, 4700)]
    [InlineData(LoyaltyTier.Silver, 19999, 18400)]
    [InlineData(LoyaltyTier.Silver, 20000, 18000)]
    // The ceiling holds the effective rate at 10 points, so Gold stops gaining.
    [InlineData(LoyaltyTier.Gold, 2000, 1820)]
    [InlineData(LoyaltyTier.Gold, 10000, 9000)]
    [InlineData(LoyaltyTier.Gold, 20000, 18000)]
    // A part cent of discount is dropped, never rounded up.
    [InlineData(LoyaltyTier.Silver, 3010, 2800)]
    [InlineData(LoyaltyTier.Bronze, 25012, 23012)]
    public void PayableTotalVariesByLoyaltyTierAndOrderSize(LoyaltyTier tier, int subtotalCents, int expectedPayableCents)
    {
        var sut = new CalculatePayableTotal();

        var payableCents = sut.For(tier, subtotalCents);

        Assert.Equal(expectedPayableCents, payableCents);
    }
}

