using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class CalculatePayableTotal
{
    private const int DiscountCeilingPoints = 10;

    public int For(LoyaltyTier tier, int subtotalCents)
    {
        var baseRatePoints = tier switch
        {
            LoyaltyTier.Bronze => 5,
            LoyaltyTier.Silver => 7,
            LoyaltyTier.Gold => 9,
        };

        var orderSizeBonusPoints = subtotalCents switch
        {
            >= 20000 => 3,
            >= 5000 => 1,
            _ => 0,
        };

        var effectiveRatePoints = Math.Min(baseRatePoints + orderSizeBonusPoints, DiscountCeilingPoints);

        var discountCents = subtotalCents * effectiveRatePoints / 100;

        return subtotalCents - discountCents;
    }
}
EOF
